import { DefinitionApi } from "@/api/workflow/modeling/definitionApi";
import hussarRequest from '@/views/workflow/util/request';
import flowfile from "../flowFile/flowfile";
export default {
  name: 'Definition',
  components: {
    flowfile: flowfile
  },
  // 版本管理页面
  props: {
    mykey: {
      type: String
    }
  },
  data: function data() {
    return {
      showPicFlag: false,
      showPicProcessInstanceId: '',
      showPicProcessKey: '',
      // 查询条件
      listQuery: {
        definitionKey: this.mykey,
        page: 1,
        size: 10
      },
      setMain: {
        processKey: this.mykey,
        id: ''
      },
      // 列表数据
      list: [],
      listLoading: false,
      // 列表选择的数据集合
      checkBoxData: [],
      // 总页数
      total: 0,
      pageCount: 7,
      // 分页参数
      page: {
        currentPage: 1,
        size: 10,
        sizes: [10, 20, 50, 100]
      }
    };
  },
  watch: {
    mykey: function mykey() {
      this.listQuery.definitionKey = this.mykey;
      this.setMain.processKey = this.mykey;
      this.queryDefinition();
    }
  },
  mounted: function mounted() {
    this.queryDefinition();
  },
  methods: {
    deleteModelWithVersion: function deleteModelWithVersion(id) {
      var _this = this;
      hussarRequest.post(DefinitionApi.delete, id).then(function (res) {
        if (res.code === 10000) {
          _this.$message.success(_this.$hussarT('hussar-modeling.deleteSuccess'));
          _this.queryDefinition();
        }
      }).catch(function (res) {});
    },
    // 设置序号
    indexMethod: function indexMethod(index) {
      var curpage = this.page.currentPage;
      var limitpage = this.listQuery.size;
      return index + 1 + (curpage - 1) * limitpage;
    },
    // 设置为主版本
    setThisMain: function setThisMain(id) {
      var _this2 = this;
      this.setMain.id = id;
      hussarRequest.get(DefinitionApi.setMain, this.setMain).then(function (res) {
        if (res.code === 10000) {
          _this2.$message.success(_this2.$hussarT('hussar-modelEdit.setSu'));
          _this2.queryDefinition();
        } else if (res.code === 30004) {
          _this2.$message.error(_this2.$hussarT('hussar-modelEdit.notFind'));
        }
      }).catch(function (res) {});
    },
    // 取消主版本
    cancelThisMain: function cancelThisMain(id) {
      var _this3 = this;
      this.setMain.id = id;
      hussarRequest.get(DefinitionApi.cancelMain, this.setMain).then(function (res) {
        if (res.code === 10000) {
          _this3.$message.success(_this3.$hussarT('hussar-common.changedSuccessful'));
          _this3.queryDefinition();
        } else if (res.code === 30004) {
          _this3.$message.error(_this3.$hussarT('hussar-modelEdit.notFind'));
        }
      }).catch(function (res) {});
    },
    // 工作流查看
    showBpm: function showBpm(data) {
      this.showPicFlag = true;
      this.showPicProcessInstanceId = data.id;
      this.showPicProcessKey = this.mykey;
    },
    close: function close() {
      this.showPicFlag = false;
    },
    // 查询列表的数据
    queryDefinition: function queryDefinition() {
      var _this4 = this;
      this.listLoading = true;
      this.listQuery.current = this.listQuery.page;
      hussarRequest.get(DefinitionApi.list, this.listQuery).then(function (res) {
        if (res.code === 10000) {
          _this4.listLoading = false;
          _this4.list = res.data.records;
          _this4.total = res.data.total;
        }
      }).catch(function (res) {
        _this4.listLoading = false;
      });
    },
    // 下载文件
    downloadFiles: function downloadFiles(deploymentId, resourceName, name) {
      var _this5 = this;
      var data = {
        'deploymentId': deploymentId,
        'resourceName': resourceName
      };
      hussarAxiosRequestUtils.downFile(DefinitionApi.downloadFiles, data).then(function (res) {
        var content = res;
        var blob = new Blob([content]);
        var fileName = name + '.zip';
        if ('download' in document.createElement('a')) {
          var elink = document.createElement('a');
          elink.download = fileName;
          elink.style.display = 'none';
          elink.href = URL.createObjectURL(blob);
          document.body.appendChild(elink);
          elink.click();
          URL.revokeObjectURL(elink.href); // 释放URL 对象
          document.body.removeChild(elink);
        }
      }).catch(function (res) {
        _this5.$message.error(_this5.$hussarT('hussar-modeling.exportError'));
      });
    },
    // 每页条数改变
    handleSizeChange: function handleSizeChange(val) {
      // 改变每页显示的条数
      this.listQuery.size = val;
      // 注意：在改变每页显示的条数时，要将页码显示到第一页
      this.listQuery.page = 1;
      this.queryDefinition();
    },
    // 页码切换
    handleCurrentChange: function handleCurrentChange(val) {
      this.listQuery.page = val;
      this.queryDefinition();
    }
  }
};
